  ('8af718c6-ca11-482b-9d6b-832f2b767928', '4740c507-d810-40b8-934c-5fe8df821f3c', '2dee0043-3f54-4802-8cf7-a671ddd9a1f1', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$In Fig. 2.6, joining (–1, –3) and (4, 12) using a ruler would show these points lie on a straight line with slope 2/5.$qbx$, 'true_false'::question_type, $qbx$[{"id":"t","text":"True"},{"id":"f","text":"False"}]$qbx$::jsonb, $qbx$False$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-27-941Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
